var frac = 24;

var slope = 0.8;
var sc = 1.8;
var nx,ny;
var TH = 0;
var depth = 1;

var one,two,shift;

function setup(){
  createCanvas(512, 512);
  noSmooth();
  background(0);
}

function draw(){

  one = new PVector(0,height/2);
  two = new PVector(width-0,height/2);

noiseSeed(98797);


  fill(0,5);
  noStroke();
  rect(0,0,width,height);

tint(255,10);
  image(g,random(-2,2),random(-2,2));
  nx = noise(frameCount/1000.0,0)*sc;
   ny = noise(0,frameCount/1000.0)*sc;

  stroke(255,10);


  for(let i= 0 ; i < frac;i++){
    TH = frameCount/200.0+i*(TWO_PI/frac);
    pushMatrix();
    translate(width/2,height/2);
    rotate(-TH);
    translate(-width/2,-height/2);

    fractal(one,two,depth);
    popMatrix();
  }


}

function fractal(p1,p2,depth){

  let d = dist(p1.x,p1.y,p2.x,p2.y);
  if(d>=1.5){
    let theta = atan2(p2.y-p1.y,p2.x-p1.x)+(frameCount)/(((1/depth))*200.0);

    let p3 = 
      new PVector(
          (p1.x+p2.x)/2.0+cos(theta)*nx*d/2.0,
          (p1.y+p2.y)/2.0+sin(theta)*nx*d/2.0);

    stroke(lerpColor("#ffcc00","#00ccff",map(theta,-PI,PI,0,1)),10);
    if(d<50)
      line(p1.x,p1.y,p2.x,p2.y);
    depth *= slope;

    if(depth >= 0.1){
      fractal(p1,p3,depth);
      fractal(p2,p3,depth);
    }
  }
}
